import sympy as sp; x = sp.Symbol('x'); f = sp.Piecewise((-x, x <= 0), (x-1, (x > 0) & (x <= 2)), (2*x-3, x > 2)); p_test = x**2*(x-2); product = p_test * f**2; cont_0 = sp.limit(product, x, 0, '-') - sp.limit(product, x, 0, '+'); cont_2 = sp.limit(product, x, 2, '-') - sp.limit(product, x, 2, '+'); print('VERIFY_PASS' if abs(float(cont_0)) < 1e-10 and abs(float(cont_2)) < 1e-10 else 'VERIFY_FAIL')